import json

s3 = session.client("s3")
assert "acme-secure-uploads" in [b["Name"] for b in s3.list_buckets()["Buckets"]]
policy = json.loads(s3.get_bucket_policy(Bucket="acme-secure-uploads")["Policy"])


def as_list(value):
    return value if isinstance(value, list) else [value]


def denies_insecure(statement, arn):
    if statement.get("Effect") != "Deny":
        return False
    if statement.get("Principal") not in ("*", {"AWS": "*"}, {"AWS": ["*"]}):
        return False
    if "s3:*" not in as_list(statement.get("Action")):
        return False
    if arn not in as_list(statement.get("Resource")):
        return False
    secure = statement.get("Condition", {}).get("Bool", {}).get("aws:SecureTransport")
    return [str(v).lower() for v in as_list(secure)] == ["false"]


statements = as_list(policy["Statement"])
for arn in ("arn:aws:s3:::acme-secure-uploads", "arn:aws:s3:::acme-secure-uploads/*"):
    assert any(denies_insecure(s, arn) for s in statements), arn

