            tag_set = s3.get_bucket_tagging(Bucket=name)["TagSet"]
        except ClientError as exc:
            if exc.response["Error"]["Code"] == "NoSuchTagSet":
                continue
            raise
        tags = {t["Key"]: t["Value"] for t in tag_set}
        if "team" in tags:
            teams[name] = tags["team"]
    return teams

